 "content": "def transform(grid):
    """Fill bounded aligned gaps; long horizontal strokes are not vertical anchors."""
    from collections import Counter
    h, w = len(grid), len(grid[0])
    counts = Counter(x for row in grid for x in row)
    bg = counts.most_common(1)[0][0]
    marker = max((x for x in counts if x != bg), key=counts.get)
    out = [row[:] for row in grid]

    # Horizontal gaps are completed between consecutive marker cells.
    for r in range(h):
        points = [c for c in range(w) if grid[r][c] == marker]
        for a, b in zip(points, points[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 2

    # Cells belonging to substantial horizontal strokes are guide bars, not
    # endpoints for vertical interpolation.
    horizontal_bar = set()
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] != marker:
                c += 1
                continue
            end = c + 1
            while end < w and grid[r][end] == marker:
                end += 1
            if end - c >= 5:
                horizontal_bar.update((r, x) for x in range(c, end))
            c = end

    for c in range(w):
        points = [r for r in range(h)
                  if grid[r][c] == marker and (r, c) not in horizontal_bar]
        for a, b in zip(points, points[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 2
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
